import { WorkItem } from '../types';

// 模拟数据库中的作品数据
const generateWorksData = (): WorkItem[] => {
  return Array.from({ length: 100 }, (_, i) => {
    const id = i + 1;
    return {
      id,
      title: `Project ${id}`,
      description: `This is a description for project ${id}. It contains more detailed information about the project requirements and goals.`,
      image: `/images/${(id % 16) + 1}.jpg`, // 循环使用16张图片
      budget: Math.floor(Math.random() * 10000) + 1000,
      dueDate: new Date(Date.now() + Math.random() * 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
    };
  });
};

const allWorksData = generateWorksData();

export const worksService = {
  // 分页获取作品数据
  getWorks: async (page: number, pageSize: number = 10): Promise<{
    data: WorkItem[];
    hasMore: boolean;
    total: number;
  }> => {
    // 模拟网络延迟
    await new Promise(resolve => setTimeout(resolve, 800 + Math.random() * 400));
    
    const startIndex = (page - 1) * pageSize;
    const endIndex = startIndex + pageSize;
    const data = allWorksData.slice(startIndex, endIndex);
    
    return {
      data,
      hasMore: endIndex < allWorksData.length,
      total: allWorksData.length,
    };
  },

  // 获取首屏数据（根据屏幕高度计算）
  getInitialWorks: async (): Promise<{
    data: WorkItem[];
    hasMore: boolean;
    total: number;
  }> => {
    // 模拟网络延迟
    await new Promise(resolve => setTimeout(resolve, 500 + Math.random() * 300));
    
    // 首屏默认加载12个卡片
    const initialCount = 12;
    const data = allWorksData.slice(0, initialCount);
    
    return {
      data,
      hasMore: initialCount < allWorksData.length,
      total: allWorksData.length,
    };
  }
};
